CREATE TABLE IF NOT EXISTS travel_contents (id INTEGER PRIMARY KEY AUTOINCREMENT,site_key TEXT NOT NULL DEFAULT 'travel',content_type TEXT NOT NULL DEFAULT 'page' CHECK(content_type IN ('page','destination','service','article')),slug TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),locale TEXT NOT NULL DEFAULT 'fa',title TEXT NOT NULL,excerpt TEXT,body TEXT NOT NULL DEFAULT '',meta_title TEXT,meta_description TEXT,featured_image TEXT,sort_order INTEGER NOT NULL DEFAULT 0,author_id INTEGER REFERENCES users(id) ON DELETE SET NULL,published_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(site_key,slug,locale));
CREATE INDEX IF NOT EXISTS idx_travel_contents_lookup ON travel_contents(site_key,status,content_type,locale);
